<link rel="stylesheet" href="<?=asset('css/communication.css')?>"><main class="write-main comm-main"><header class="comm-heading"><div><span class="writer-kicker">Private device access</span><h1>Devices & passkeys</h1><p>Control where your workspace can be opened.</p></div><a class="wbtn" href="<?=url('/write/app')?>">App preferences</a></header><?php foreach(flashes()as$f):?><p class="notice" role="status"><?=e($f['message'])?></p><?php endforeach;?><?php if($error):?><p class="notice error" role="alert"><?=e($error)?></p><?php endif;?><div class="comm-columns"><section class="comm-panel"><h2>Passkeys</h2><p>Use your device’s supported fingerprint, face recognition, screen lock or security key. Biometric data stays with your authenticator.</p><form data-register-passkey><?=csrf_field()?><label>Passkey name<input name="label" maxlength="80" required placeholder="My phone"></label><label>Current Writer password<input type="password" name="password" autocomplete="current-password" required></label><button class="wbtn primary">Add passkey</button></form><p role="status" data-security-status></p><?php foreach($passkeys as$p):?><article class="comm-row"><h3><?=e($p['label'])?></h3><p>Added <?=e(date('j M Y',$p['created']))?></p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="remove_passkey"><input type="hidden" name="id" value="<?=e($p['id'])?>"><label>Current password to remove<input type="password" name="password" autocomplete="current-password" required></label><button class="wbtn" data-confirm-action="Remove this passkey?">Remove passkey</button></form></article><?php endforeach;?></section><section class="comm-panel"><h2>Signed-in sessions</h2><p>Sessions appear as they use the website after this update. Revocation takes effect on their next request.</p><?php foreach($sessions as$s):?><article class="comm-row"><h3><?=$s['id']===app_device_id()?'This session':'Browser session'?> · <?=!empty($s['revoked'])?'Revoked':'Active'?></h3><p><?=e($s['label'])?></p><small>Last seen <?=e(date('j M Y H:i T',$s['seen']))?></small><?php if(empty($s['revoked'])):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="revoke_session"><input type="hidden" name="id" value="<?=e($s['id'])?>"><button class="wbtn" data-confirm-action="Sign out this session?">Sign out session</button></form><?php endif;?></article><?php endforeach;?></section></div></main>
